/**
 * Generates the complete iOS app icon set for BeenBy from one source image.
 *
 * Usage:
 *   node scripts/generate-ios-icon.mjs [path-to-source.png]
 *
 * Default source: assets/app-icon.png
 *
 * The generated asset catalog contains every required iPhone and iPad icon,
 * plus the 1024x1024 App Store marketing icon. The script:
 *   1. Flattens transparency onto white (App Store rejects icons with alpha).
 *   2. Resizes/crops each output to a full-bleed square.
 *   3. Writes all PNGs and Contents.json to AppIcon.appiconset.
 *
 * The iOS project is generated by `npx cap add ios` and is not in git, so the
 * script creates the folder if needed and can be re-run after every sync.
 * Requires ImageMagick (`magick`) on PATH.
 */
import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  unlinkSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";

const source = process.argv[2] ?? "assets/app-icon.png";
const OUT_DIR = "ios/App/App/Assets.xcassets/AppIcon.appiconset";

const icons = [
  { idiom: "iphone", size: "20x20", scale: "2x", pixels: 40 },
  { idiom: "iphone", size: "20x20", scale: "3x", pixels: 60 },
  { idiom: "iphone", size: "29x29", scale: "2x", pixels: 58 },
  { idiom: "iphone", size: "29x29", scale: "3x", pixels: 87 },
  { idiom: "iphone", size: "40x40", scale: "2x", pixels: 80 },
  { idiom: "iphone", size: "40x40", scale: "3x", pixels: 120 },
  { idiom: "iphone", size: "60x60", scale: "2x", pixels: 120 },
  { idiom: "iphone", size: "60x60", scale: "3x", pixels: 180 },
  { idiom: "ipad", size: "20x20", scale: "1x", pixels: 20 },
  { idiom: "ipad", size: "20x20", scale: "2x", pixels: 40 },
  { idiom: "ipad", size: "29x29", scale: "1x", pixels: 29 },
  { idiom: "ipad", size: "29x29", scale: "2x", pixels: 58 },
  { idiom: "ipad", size: "40x40", scale: "1x", pixels: 40 },
  { idiom: "ipad", size: "40x40", scale: "2x", pixels: 80 },
  { idiom: "ipad", size: "76x76", scale: "1x", pixels: 76 },
  { idiom: "ipad", size: "76x76", scale: "2x", pixels: 152 },
  { idiom: "ipad", size: "83.5x83.5", scale: "2x", pixels: 167 },
  { idiom: "ios-marketing", size: "1024x1024", scale: "1x", pixels: 1024 },
].map((icon) => ({
  ...icon,
  filename:
    icon.idiom === "ios-marketing"
      ? "AppIcon-1024.png"
      : `AppIcon-${icon.idiom}-${icon.size.split("x")[0]}@${icon.scale}.png`,
}));

if (!existsSync(source)) {
  console.error(`Hittar inte källbilden ${source}.`);
  console.error("Lägg en kvadratisk bild där eller ange sökväg:");
  console.error("  node scripts/generate-ios-icon.mjs /sökväg/till/ikon.png");
  process.exit(1);
}

mkdirSync(OUT_DIR, { recursive: true });

for (const filename of readdirSync(OUT_DIR)) {
  if (filename.toLowerCase().endsWith(".png")) {
    unlinkSync(join(OUT_DIR, filename));
  }
}

for (const icon of icons) {
  const geometry = `${icon.pixels}x${icon.pixels}`;
  execFileSync("magick", [
    source,
    "-resize",
    `${geometry}^`, // fyll hela ytan, beskär överskott
    "-gravity",
    "center",
    "-extent",
    geometry,
    "-background",
    "white",
    "-alpha",
    "remove", // ingen alfa — App Store-krav
    "-strip",
    join(OUT_DIR, icon.filename),
  ]);
}

writeFileSync(
  join(OUT_DIR, "Contents.json"),
  JSON.stringify(
    {
      images: icons.map(({ idiom, size, scale, filename }) => ({
        size,
        idiom,
        filename,
        scale,
      })),
      info: { version: 1, author: "xcode" },
    },
    null,
    2,
  ) + "\n",
);

console.log(
  `${icons.length} appikoner genererade i ${OUT_DIR} (iPhone, iPad och App Store; utan alfa).`,
);
console.log("Öppna Xcode och bygg om — hela ikonuppsättningen plockas upp automatiskt.");
